// Generated by AI (UnitTest MCP)
import { existsSync, mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname } from "node:path";

import { afterEach, describe, expect, it } from "vitest";

import { reserveWorktreePath } from "./reserve-worktree-path.mjs";

const temporaryDirectories = [];
afterEach(() => {
  for (const directory of temporaryDirectories.splice(0)) {
    rmSync(directory, { recursive: true, force: true });
  }
});

describe("reserveWorktreePath", () => {
  it("reserves a real, unique parent directory and a not-yet-created child path", () => {
    const { parent, path } = reserveWorktreePath("reserve-worktree-path-test-");
    temporaryDirectories.push(parent);

    // Not the bare OS temp directory itself: a genuinely reserved, unique
    // directory nothing else could already occupy or collide with.
    expect(parent).not.toBe(tmpdir());
    expect(existsSync(parent)).toBe(true);

    expect(dirname(path)).toBe(parent);
    expect(existsSync(path)).toBe(false);
  });

  it("never deletes anything to make room for the reserved path", () => {
    // The defect this replaces: mkdtempSync a directory, then rmSync it so
    // `git worktree add` could recreate it at the same name. Proving the
    // fixed helper only ever CREATES the parent (never removes the child it
    // returns) is the property that eliminates the create/delete/recreate
    // race by construction.
    let mkdtempCalls = 0;
    const countingMkdtemp = (prefix) => {
      mkdtempCalls += 1;
      return mkdtempSync(prefix);
    };

    const { parent } = reserveWorktreePath("reserve-worktree-path-test-", {
      mkdtemp: countingMkdtemp,
    });
    temporaryDirectories.push(parent);

    expect(mkdtempCalls).toBe(1);
    expect(existsSync(parent)).toBe(true);
  });

  it("reserves distinct parents across repeated calls with the same prefix", () => {
    const first = reserveWorktreePath("reserve-worktree-path-test-");
    const second = reserveWorktreePath("reserve-worktree-path-test-");
    temporaryDirectories.push(first.parent, second.parent);

    expect(first.parent).not.toBe(second.parent);
    expect(first.path).not.toBe(second.path);
  });
});
